actions.script:
found = false; visible = false; request = null; project = null; canTriage = false; canManageProject = false
isRaiser = false; isAssignee = false; isParty = false
const access = ec.service.sync().name('ironstone.commons.RequestServices.get#RequestAccess').parameters({requestId: requestId, need: 'check'}).call() || {}
found = !!access.found
visible = !!access.visible
if (!visible) {
    if (need !== 'check') ec.message.addError(ec.resource.expand('Request ${requestId} is not available', '', {requestId}))
    return
}
request = access.request
isRaiser = !!access.isRaiser
isAssignee = !!access.isAssignee
isParty = !!access.isParty
const projects = ec.user.isInGroup('BOSS_PROJECT_TEAM') || ec.user.isInGroup('BOSS_PROJECT_MANAGER') || ec.user.isInGroup('ADMIN')
if (request.rootWorkEffortId) {
    const projectAccess = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: request.rootWorkEffortId,
        need: 'none'}).call() || {}
    project = projectAccess.project || null
    canTriage = !!projectAccess.canUpdate
    canManageProject = !!projectAccess.canManage
} else {
    canTriage = projects
}
if (need === 'triage' && !canTriage) ec.message.addError(ec.resource.expand('You may not triage request ${requestId}', '', {requestId}))

const lists = ['new', 'assigned', 'review', 'accepted', 'progress', 'mine', 'closed', 'all']
const isManager = ec.user.isInGroup('BOSS_PROJECT_MANAGER') || ec.user.isInGroup('ADMIN')
if (!lists.includes(list)) list = isManager ? 'new' : 'assigned'
rowList = []; rowCount = 0; pageMaxIndex = 0; pageRangeLow = 0; pageRangeHigh = 0
counts = {}
for (const key of lists) counts[key] = 0
const cf = ec.entity.conditionFactory
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
const me = vis.userPartyId || null
// what the user sees: the visible projects' requests, and the triaged types with no project
const reach = []
if (vis.allProjects) reach.push(cf.makeCondition('rootWorkEffortId', 'is-not-null', null))
else if (Array.from(vis.visibleProjectIds || []).length) reach.push(cf.makeCondition('rootWorkEffortId', 'in', Array.from(vis.visibleProjectIds)))
const triaged = new Set()
const orgIds = Array.from(vis.orgIds || [])
for (const setting of ec.entity.find('mantle.party.PartySetting').condition('partySettingTypeId', 'ProjIntake')
        .condition(vis.allProjects ? cf.makeCondition('partyId', 'is-not-null', null) : cf.makeCondition('partyId', 'in', orgIds.length ? orgIds : ['_NA_'])).list())
    for (const id of Array.from(ec.service.sync().name('mantle.request.RequestServices.get#IntakeSettings').parameters({organizationPartyId: setting.partyId})
            .call()?.settings?.triagedTypes || [])) triaged.add(id)
// a request in a service queue (a case, or one held for review there) is Customer Service's, not Projects' triage (impl-customer-service P6)
const serviceQueueIds = triaged.size ? Array.from(new Set(Array.from(ec.entity.find('mantle.request.support.ServiceQueue')
        .condition(cf.makeCondition('fromDate', 'is-not-null', null)).conditionDate('fromDate', 'thruDate', ec.user.nowTimestamp)
        .selectField('requestCategoryId').disableAuthz().list()).map((row) => row.requestCategoryId))) : []
if (triaged.size) reach.push(cf.makeCondition([cf.makeCondition('rootWorkEffortId', 'equals', null), cf.makeCondition('requestTypeEnumId', 'in', Array.from(triaged)),
    cf.makeCondition([cf.makeCondition('requestCategoryId', 'equals', null), cf.makeCondition('requestCategoryId', 'not-in', serviceQueueIds.length ? serviceQueueIds : ['_NONE_'])], 'or')], 'and'))
if (!reach.length) return
let find = ec.entity.find('mantle.request.Request').condition(cf.makeCondition(reach, 'or'))
// a purchase RFQ is in no Projects list (impl-purchasing P11, R-PUR-13)
find = find.condition(cf.makeCondition([cf.makeCondition('requestTypeEnumId', 'is-null', null),
        cf.makeCondition('requestTypeEnumId', 'not-equals', 'RqtPurchaseRfq')], 'or'))
if (rootWorkEffortId) find = find.condition('rootWorkEffortId', rootWorkEffortId)
else if (noProject) find = find.condition('rootWorkEffortId', null)
const all = Array.from(find.orderBy('-lastUpdatedStamp').limit(5000).list())
if (!all.length) return
const ids = all.map((row) => row.requestId)
// the parties: assignee, customer, reporter (current)
const roles = {}
for (const rp of ec.entity.find('mantle.request.RequestParty').condition('requestId', 'in', ids).condition('roleTypeId', 'in', ['Assignee', 'Customer', 'Reporter'])
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).orderBy('-fromDate').list()) {
    const key = rp.requestId + '|' + rp.roleTypeId
    if (!roles[key]) roles[key] = rp.partyId
}
const closedOf = (row) => ['ReqCompleted', 'ReqCancelled'].includes(row.statusId)
const isMine = (row) => !!me && (row.filedByPartyId === me || roles[row.requestId + '|Reporter'] === me)
const fits = {
    new: (row) => row.statusId === 'ReqSubmitted' && !roles[row.requestId + '|Assignee'],
    assigned: (row) => !closedOf(row) && !!me && roles[row.requestId + '|Assignee'] === me,
    review: (row) => row.statusId === 'ReqSubmitted',
    accepted: (row) => row.statusId === 'ReqReviewed',
    progress: (row) => row.statusId === 'ReqInProgress',
    mine: (row) => !closedOf(row) && isMine(row),
    closed: (row) => closedOf(row),
    all: () => true
}
for (const key of lists) counts[key] = all.filter(fits[key]).length

// the find
const statusIds = statusId ? String(statusId).split(',').map((id) => id.trim()).filter((id) => id) : []
const typeIds = requestTypeEnumId ? String(requestTypeEnumId).split(',').map((id) => id.trim()).filter((id) => id) : []
const words = text ? String(text).trim().toLowerCase() : ''
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const textValue = String(value)
    if (/^-?\d+$/.test(textValue)) return Number(textValue)
    const parsed = Date.parse(textValue)
    return Number.isNaN(parsed) ? null : parsed
}
const fromMillis = toMillis(dateFrom), thruMillis = toMillis(dateThru)
const bands = {high: [1, 3], normal: [4, 6], low: [7, 9]}
const channelOf = (row) => row.salesChannelEnumId === 'ScEmail' ? 'email' : (row.salesChannelEnumId === 'ScWeb' ? 'form' : 'app')
const rows = all.filter((row) => {
    if (statusIds.length ? !statusIds.includes(row.statusId) : !fits[list](row)) return false
    if (typeIds.length && !typeIds.includes(row.requestTypeEnumId)) return false
    if (priorityBand && bands[priorityBand]) { const value = row.priority ?? null; if (value == null || value < bands[priorityBand][0] || value > bands[priorityBand][1]) return false }
    if (assigneePartyId && roles[row.requestId + '|Assignee'] !== assigneePartyId) return false
    if (customerPartyId && roles[row.requestId + '|Customer'] !== customerPartyId) return false
    if (channel && channelOf(row) !== channel) return false
    if (fromMillis != null || thruMillis != null) {
        const date = toMillis(row.requestDate)
        if (date == null || (fromMillis != null && date < fromMillis) || (thruMillis != null && date >= thruMillis)) return false
    }
    if (words && !(String(row.requestName || '').toLowerCase().includes(words) || String(row.description || '').toLowerCase().includes(words)
            || String(row.requestId).toLowerCase() === words)) return false
    return true
})
const sortKey = orderByField ? String(orderByField).replace(/^[+^]/, '') : ''
const desc = sortKey.startsWith('-')
const field = desc ? sortKey.substring(1) : sortKey
const updatedOf = (row) => toMillis(row.lastUpdatedStamp) ?? toMillis(row.requestDate) ?? 0
const comparators = {
    requestId: (left, right) => String(left.requestId).localeCompare(String(right.requestId), undefined, {numeric: true}),
    requestName: (left, right) => String(left.requestName || '').localeCompare(String(right.requestName || '')),
    priority: (left, right) => (left.priority ?? 99) - (right.priority ?? 99) || updatedOf(right) - updatedOf(left),
    statusId: (left, right) => String(left.statusId || '').localeCompare(String(right.statusId || '')),
    requestDate: (left, right) => (toMillis(left.requestDate) ?? 0) - (toMillis(right.requestDate) ?? 0),
    responseRequiredDate: (left, right) => (toMillis(left.responseRequiredDate) ?? Number.MAX_SAFE_INTEGER) - (toMillis(right.responseRequiredDate) ?? Number.MAX_SAFE_INTEGER),
    lastUpdatedStamp: (left, right) => updatedOf(left) - updatedOf(right),
    rootWorkEffortId: (left, right) => String(left.rootWorkEffortId || '').localeCompare(String(right.rootWorkEffortId || ''))
}
if (comparators[field]) { rows.sort(comparators[field]); if (desc) rows.reverse() }
else rows.sort((left, right) => updatedOf(right) - updatedOf(left))

rowCount = rows.length
const size = pageNoLimit ? Math.max(1, Math.min(rowCount, 500)) : Math.max(1, Math.min(Number(pageSize) || 25, 200))
pageSize = size
pageMaxIndex = rowCount ? Math.floor((rowCount - 1) / size) : 0
pageIndex = pageNoLimit ? 0 : Math.min(Math.max(0, Number(pageIndex) || 0), pageMaxIndex)
const page = rows.slice(pageIndex * size, (pageIndex + 1) * size)
pageRangeLow = rowCount ? pageIndex * size + 1 : 0
pageRangeHigh = Math.min((pageIndex + 1) * size, rowCount)
if (!page.length) return
rowList = Array.from(ec.service.sync().name('ironstone.projects.ProjectRequestServices.decorate#RequestRows').parameters({requestList: page.map((row) => row.getMap()),
    roleMap: roles}).call()?.rowList || [])

rowList = []
const requests = Array.from(requestList || [])
if (!requests.length) return
const cf = ec.entity.conditionFactory
const L = (text) => ec.l10n.localize(text)
const ids = requests.map((row) => row.requestId)
const roles = Object.assign({}, roleMap || {})
if (!roleMap) for (const rp of ec.entity.find('mantle.request.RequestParty').condition('requestId', 'in', ids).condition('roleTypeId', 'in', ['Assignee', 'Customer', 'Reporter'])
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).orderBy('-fromDate').list()) {
    const key = rp.requestId + '|' + rp.roleTypeId
    if (!roles[key]) roles[key] = rp.partyId
}
const partyIds = Array.from(new Set(Object.values(roles).filter((id) => id)))
const names = {}
if (partyIds.length) for (const party of ec.entity.find('mantle.party.PartyDetail').condition('partyId', 'in', partyIds).list())
    names[party.partyId] = party.privateOwnerUserId && party.privateOwnerUserId !== ec.user.userId ? party.partyId
        : (party.organizationName || [party.firstName, party.lastName].filter((name) => name).join(' ') || party.pseudoId || party.partyId)
const projectIds = Array.from(new Set(requests.map((row) => row.rootWorkEffortId).filter((id) => id)))
const projectNames = {}
if (projectIds.length) for (const project of ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', projectIds).list())
    projectNames[project.workEffortId] = project.workEffortName || project.workEffortId
// the work: done of the linked work items
const work = {}
const links = Array.from(ec.entity.find('mantle.request.RequestWorkEffort').condition('requestId', 'in', ids).list())
const itemIds = Array.from(new Set(links.map((link) => link.workEffortId)))
const itemStatus = {}
if (itemIds.length) for (const item of ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js').without(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', itemIds)
        .condition('workEffortTypeEnumId', 'WetTask')).selectField('workEffortId,statusId').list()) itemStatus[item.workEffortId] = item.statusId
for (const link of links) {
    if (!(link.workEffortId in itemStatus)) continue
    const entry = work[link.requestId] || (work[link.requestId] = {done: 0, total: 0})
    entry.total++
    if (['WeComplete', 'WeClosed'].includes(itemStatus[link.workEffortId])) entry.done++
}
const statusIds = Array.from(new Set(requests.map((row) => row.statusId).filter((id) => id)))
const colors = ec.service.sync().name('org.moqui.ui.StatusServices.get#StatusColors').parameters({statusIdList: statusIds}).call()?.colors || {}
const statusLabel = (id) => id ? (ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()?.description || id) : ''
const enumLabel = (id) => id ? (ec.entity.find('moqui.basic.Enumeration').condition('enumId', id).useCache(true).one()?.description || id) : ''
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const fmt = (millis, format) => ec.l10n.format(new Date(Number(millis)), format)
const nowMillis = toMillis(ec.user.nowTimestamp)
const thisYear = fmt(nowMillis, 'yyyy')
const dateText = (millis) => millis == null ? '' : fmt(millis, fmt(millis, 'yyyy') === thisYear ? 'MMM d' : 'MMM d, yyyy')
const me = ec.user.userAccount?.partyId || null
const channels = {ScEmail: ['email', 'Email', 'sym_o_mail'], ScWeb: ['form', 'Form', 'sym_o_web']}
for (const row of requests) {
    const id = row.requestId
    const assignee = roles[id + '|Assignee'] || null, customer = roles[id + '|Customer'] || null
    const due = toMillis(row.responseRequiredDate)
    const closed = ['ReqCompleted', 'ReqCancelled'].includes(row.statusId)
    const channel = channels[row.salesChannelEnumId] || ['app', 'App', 'sym_o_apps']
    const done = work[id] || {done: 0, total: 0}
    rowList.push({requestId: id, requestName: row.requestName || id, url: '/qapps/Projects/Requests/RequestDetail?requestId=' + encodeURIComponent(id),
        requestTypeEnumId: row.requestTypeEnumId || null, typeLabel: enumLabel(row.requestTypeEnumId),
        statusId: row.statusId || null, statusLabel: statusLabel(row.statusId), statusColor: colors[row.statusId] || 'grey-7', isClosed: closed,
        rootWorkEffortId: row.rootWorkEffortId || null, projectName: row.rootWorkEffortId ? (projectNames[row.rootWorkEffortId] || row.rootWorkEffortId) : '',
        customerPartyId: customer, customerName: customer ? (names[customer] || customer) : '',
        assigneePartyId: assignee, assigneeName: assignee ? (names[assignee] || assignee) : '', isMine: !!me && assignee === me,
        priority: row.priority ?? null, priorityText: row.priority != null ? String(row.priority) : '',
        responseRequiredDate: due != null ? ec.l10n.format(new Date(due), 'yyyy-MM-dd') : null, dueText: dateText(due), overdue: !closed && due != null && due < nowMillis,
        channel: channel[0], channelLabel: L(channel[1]), channelIcon: channel[2], workDone: done.done, workTotal: done.total,
        workText: done.total ? done.done + '/' + done.total : '', requestDateText: dateText(toMillis(row.requestDate)),
        updatedText: dateText(toMillis(row.lastUpdatedStamp) ?? toMillis(row.requestDate)),
        statusId_display: statusLabel(row.statusId), assigneePartyId_display: assignee ? (names[assignee] || assignee) : '',
        rootWorkEffortId_display: row.rootWorkEffortId ? (projectNames[row.rootWorkEffortId] || row.rootWorkEffortId) : '',
        requestTypeEnumId_display: enumLabel(row.requestTypeEnumId)})
}

const L = (text) => ec.l10n.localize(text)
const name = String(requestName || '').trim()
if (!name) { ec.message.addError(L('A request needs a name')); return }
if (rootWorkEffortId) {
    ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: rootWorkEffortId, need: 'update'}).call()
    if (ec.message.hasError()) return
}
const settings = ec.service.sync().name('mantle.request.RequestServices.get#IntakeSettings').parameters({workEffortId: rootWorkEffortId || null,
    organizationPartyId: rootWorkEffortId ? null : (ec.service.sync().name('ironstone.projects.ProjectServices.get#SettingsOrganization').call()?.organizationPartyId || null)})
        .call()?.settings || {}
const typeId = requestTypeEnumId || settings.defaultType || 'RqtSupport'
if (ec.entity.find('moqui.basic.Enumeration').condition('enumId', typeId).useCache(true).one()?.enumTypeId !== 'RequestType') {
    ec.message.addError(ec.resource.expand('${id} is not a request type', '', {id: typeId})); return }
if (customerPartyId) {
    const customer = ec.entity.find('mantle.party.PartyDetail').condition('partyId', customerPartyId).one()
    if (customer == null || (customer.privateOwnerUserId && customer.privateOwnerUserId !== ec.user.userId)) {
        ec.message.addError(ec.resource.expand('Customer ${id} is not available', '', {id: customerPartyId})); return }
}
const assignee = assigneePartyId || settings.triagePartyId || null
const day = responseRequiredDate ? String(responseRequiredDate).trim().substring(0, 10) : ''
if (day && !/^\d{4}-\d{2}-\d{2}$/.test(day)) { ec.message.addError(L('A due date is yyyy-MM-dd')); return }
const out = ec.service.sync().name('mantle.request.RequestServices.create#Request').parameters({requestName: name.substring(0, 255),
    requestTypeEnumId: typeId, rootWorkEffortId: rootWorkEffortId || null, statusId: 'ReqSubmitted', description: description || null,
    priority: priority && /^[1-9]$/.test(String(priority)) ? Number(priority) : 5, customerPartyId: customerPartyId || null, assignToPartyId: assignee,
    responseRequiredDate: day ? ec.l10n.parseTimestamp(day + ' 17:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS') : null}).call()
if (ec.message.hasError()) return
requestId = out.requestId
message = ec.resource.expand('Request ${id} submitted: ${name}', '', {id: requestId, name})

const L = (text) => ec.l10n.localize(text)
const access = ec.service.sync().name('ironstone.projects.ProjectRequestServices.get#ProjectRequestAccess').parameters({requestId: requestId, need: 'triage'}).call() || {}
if (ec.message.hasError()) return
const request = access.request
const name = request.requestName || requestId
const update = (fields) => ec.service.sync().name('mantle.request.RequestServices.update#Request').parameters(Object.assign({requestId: requestId}, fields)).call()
const text = value == null ? '' : String(value).trim()
// a support case (impl-customer-service P2, F64): its resolve, cancel and reopen go through Customer Service's
// transition#Case, or are refused; its due date is refused
const caseGuard = ec.resource.script('component://mr-boss/service/ironstone/customerservice/CaseGuard.js')
switch (action) {
    case 'status': {
        if (['ReqCompleted', 'ReqCancelled'].includes(text) || request.statusId === 'ReqCompleted') {
            const routed = caseGuard.resolve(requestId, text, resolutionEnumId, comment)
            if (routed) { message = routed.message; return }
        }
        const moves = {ReqSubmitted: ['ReqReviewed', 'ReqInProgress', 'ReqCompleted', 'ReqCancelled'], ReqReviewed: ['ReqInProgress', 'ReqCompleted', 'ReqCancelled'],
            ReqInProgress: ['ReqSubmitted', 'ReqCompleted', 'ReqCancelled'], ReqCompleted: ['ReqInProgress']}
        if (!(moves[request.statusId] || []).includes(text)) {
            ec.message.addError(ec.resource.expand('A request ${status} does not move to ${to} here', '', {status: request.statusId, to: text})); return }
        const fields = {statusId: text}
        if (text === 'ReqCompleted') {
            const ok = ['RrFixed', 'RrCompleted', 'RrWontFix', 'RrDuplicate', 'RrCantReproduce', 'RrInsufficient', 'RrRejected']
            fields.requestResolutionEnumId = ok.includes(resolutionEnumId) ? resolutionEnumId : (request.requestTypeEnumId === 'RqtBugFix' ? 'RrFixed' : 'RrCompleted')
        } else if (text === 'ReqCancelled') {
            fields.requestResolutionEnumId = ['RrRejected', 'RrDuplicate', 'RrWontFix'].includes(resolutionEnumId) ? resolutionEnumId : 'RrRejected'
        } else if (text === 'ReqInProgress' && request.statusId === 'ReqCompleted') {
            fields.requestResolutionEnumId = 'RrUnresolved'
        }
        update(fields)
        if (ec.message.hasError()) return
        if (comment && String(comment).trim()) ec.service.sync().name('mantle.request.RequestServices.add#RequestComment').parameters({requestId: requestId,
            body: String(comment).trim(), contentType: 'text/plain'}).call()
        const words = {ReqReviewed: 'Accepted: ${name}', ReqInProgress: 'Started: ${name}', ReqCompleted: 'Completed: ${name}',
            ReqCancelled: 'Cancelled: ${name}', ReqSubmitted: 'Back to submitted: ${name}'}
        message = ec.resource.expand(words[text] || 'Saved: ${name}', '', {name})
        return
    }
    case 'assign': {
        if (text) {
            const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', text).one()
            if (party == null || party.disabled === 'Y' || (party.privateOwnerUserId && party.privateOwnerUserId !== ec.user.userId)) {
                ec.message.addError(ec.resource.expand('${text} is not someone a request can be assigned to', '', {text})); return }
            ec.service.sync().name('mantle.request.RequestServices.replace#RequestParty').parameters({requestId: requestId, roleTypeId: 'Assignee', newPartyId: text}).call()
            if (ec.message.hasError()) return
            message = ec.resource.expand('Assigned to ${who}', '', {who: party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || text})
        } else {
            for (const rp of ec.entity.find('mantle.request.RequestParty').condition('requestId', requestId).condition('roleTypeId', 'Assignee')
                    .conditionDate('fromDate', 'thruDate', null).list()) { rp.set('thruDate', ec.user.nowTimestamp); rp.update() }
            message = L('Unassigned')
        }
        return
    }
    case 'project': {
        if (text) {
            const projectAccess = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: text, need: 'update'}).call()
            if (ec.message.hasError()) return
            update({rootWorkEffortId: text})
            if (!ec.message.hasError()) message = ec.resource.expand('Moved to ${project}', '', {project: projectAccess.project?.workEffortName || text})
        } else {
            update({rootWorkEffortId: null})
            if (!ec.message.hasError()) message = L('Taken off its project')
        }
        return
    }
    case 'priority': {
        if (!/^[1-9]$/.test(text)) { ec.message.addError(L('A priority is 1 (highest) to 9 (lowest)')); return }
        update({priority: Number(text)})
        if (!ec.message.hasError()) message = ec.resource.expand('Priority ${priority}', '', {priority: text})
        return
    }
    case 'due': {
        caseGuard.refuseDue(requestId)
        const day = text.substring(0, 10)
        if (day && !/^\d{4}-\d{2}-\d{2}$/.test(day)) { ec.message.addError(L('A due date is yyyy-MM-dd')); return }
        update({responseRequiredDate: day ? ec.l10n.parseTimestamp(day + ' 17:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS') : null})
        if (!ec.message.hasError()) message = day ? ec.resource.expand('Due ${day}', '', {day}) : L('No due date')
        return
    }
    case 'type': {
        const type = ec.entity.find('moqui.basic.Enumeration').condition('enumId', text).useCache(true).one()
        if (type == null || type.enumTypeId !== 'RequestType') { ec.message.addError(ec.resource.expand('${text} is not a request type', '', {text})); return }
        update({requestTypeEnumId: text})
        if (!ec.message.hasError()) message = ec.resource.expand('Type ${type}', '', {type: type.description})
        return
    }
    default:
        ec.message.addError(ec.resource.expand('Unknown triage change ${action}', '', {action}))
}

doneCount = 0
failedCount = 0
const ids = Array.from(new Set(String(requestIds || '').split(',').map((id) => id.trim()).filter((id) => id))).slice(0, 500)
if (!ids.length) { ec.message.addError(ec.l10n.localize('Select the requests first')); return }
const failures = []
for (const id of ids) {
    ec.message.pushErrors()
    try {
        let service = 'ironstone.projects.ProjectRequestServices.triage#Request'
        let parameters = {requestId: id}
        switch (action) {
            case 'assign': Object.assign(parameters, {action: 'assign', value: value || ''}); break
            case 'project': Object.assign(parameters, {action: 'project', value: value || ''}); break
            case 'priority': Object.assign(parameters, {action: 'priority', value: value}); break
            case 'accept': Object.assign(parameters, {action: 'status', value: 'ReqReviewed'}); break
            case 'start': Object.assign(parameters, {action: 'status', value: 'ReqInProgress'}); break
            case 'cancel': Object.assign(parameters, {action: 'status', value: 'ReqCancelled', resolutionEnumId: value || 'RrRejected'}); break
            case 'makeWork': service = 'ironstone.projects.ProjectRequestServices.make#WorkItemFromRequest'; break
