const addressList = []
for (const row of find.list()) {
    const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', row.workEffortId).one()
    if (project == null) continue
    const intake = ec.service.sync().name('ironstone.projects.ProjectRequestServices.get#ProjectIntake').parameters({workEffortId: row.workEffortId}).call()?.intake || {}
    ec.message.clearErrors()
    addressList.push({workEffortId: row.workEffortId, projectName: project.workEffortName || row.workEffortId, accountId: intake.accountId,
        accountName: intake.accountName, plusTag: intake.plusTag, address: intake.address, makes: intake.ruleList?.[0]?.makes || 'requests',
        ruleCount: (intake.ruleList || []).length, matchedCount: (intake.ruleList || []).reduce((sum, rule) => sum + (rule.matchedCount || 0), 0),
        canManage: !!intake.canManage})
}
addressList.sort((left, right) => left.projectName.localeCompare(right.projectName))
const form = settings.publicForm || {}
info = {organizationPartyId: orgId, organizationName: org.organizationName || '', typeList: types,
    types: {offered: Array.from(settings.offeredTypes || []), triaged: Array.from(settings.triagedTypes || []), defaultType: settings.defaultType || '',
        triagePartyId: settings.triagePartyId || '', triageName: party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ')) : ''},
    categoryList: categories, addressList: addressList, accountList: accountList,
    publicForm: {captcha: form.captcha || 'N', files: form.files || 'Y', maxMb: String(form.maxMb || 10), maxFiles: String(form.maxFiles || 5), confirm: form.confirm || 'Y'},
    captchaKeysSet: !!ec.user.getPreference('reCAPTCHA.site.key')}

const L = (text) => ec.l10n.localize(text)
ec.service.sync().name('ironstone.projects.ProjectServices.check#SettingsManager').call()
if (ec.message.hasError()) return
const orgId = ec.service.sync().name('ironstone.projects.ProjectServices.get#SettingsOrganization').call()?.organizationPartyId
if (!orgId) { ec.message.addError(L('You belong to no organization, so there is nowhere to keep the setting')); return }
const known = Array.from(ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', 'RequestType').useCache(true).list()).map((row) => row.enumId)
const listOf = (value) => (value == null ? [] : (Array.isArray(value) ? value : (typeof value === 'object' && value.length != null ? Array.from(value) : String(value).split(','))))
        .map((part) => String(part).trim()).filter((part) => part && known.includes(part))
const offeredList = listOf(offered)
if (!offeredList.length) { ec.message.addError(L('Offer at least one request type')); return }
const value = {offered: offeredList.join(','), triaged: listOf(triaged).join(',')}
if (defaultType) {
    if (!offeredList.includes(defaultType)) { ec.message.addError(L('The default type is one of those offered')); return }
    value.defaultType = defaultType
}
if (triagePartyId) {
    const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', triagePartyId).one()
    if (party == null || party.disabled === 'Y') { ec.message.addError(ec.resource.expand('${id} is not someone requests can be assigned to', '', {id: triagePartyId})); return }
    value.triagePartyId = triagePartyId
}
const text = JSON.stringify(value)
if (text.length > 255) { ec.message.addError(L('Too many types for the setting: offer fewer')); return }
ec.service.sync().name('store#mantle.party.PartySetting').parameters({partyId: orgId, partySettingTypeId: 'ProjIntake', settingValue: text}).call()
if (!ec.message.hasError()) message = L('Request types saved')

const L = (text) => ec.l10n.localize(text)
ec.service.sync().name('ironstone.projects.ProjectServices.check#SettingsManager').call()
if (ec.message.hasError()) return
const orgId = ec.service.sync().name('ironstone.projects.ProjectServices.get#SettingsOrganization').call()?.organizationPartyId
if (!orgId) { ec.message.addError(L('You belong to no organization, so there is nowhere to keep the setting')); return }
const count = (value, max, label) => {
    const number = Math.floor(Number(value))
    if (!(number >= 1 && number <= max)) { ec.message.addError(ec.resource.expand('${label} is 1 to ${max}', '', {label: L(label), max})); return null }
    return number
}
const filesMax = count(maxFiles ?? 5, 10, 'Files at most')
const sizeMax = count(maxMb ?? 10, 50, 'Size of a file (MB)')
if (ec.message.hasError()) return
const yn = (value) => value === 'Y' || value === true || value === 'true' ? 'Y' : 'N'
ec.service.sync().name('store#mantle.party.PartySetting').parameters({partyId: orgId, partySettingTypeId: 'ProjPublicForm',
    settingValue: JSON.stringify({captcha: yn(captcha), files: yn(files), maxFiles: filesMax, maxMb: sizeMax, confirm: yn(confirm)})}).call()
if (!ec.message.hasError()) message = L('Public form saved')

const L = (text) => ec.l10n.localize(text)
ec.service.sync().name('ironstone.projects.ProjectServices.check#SettingsManager').call()
if (ec.message.hasError()) return
if (remove) {
    if (!requestCategoryId) { ec.message.addError(L('Choose the category')); return }
    if (ec.entity.find('mantle.request.Request').condition('requestCategoryId', requestCategoryId).count() > 0) {
        ec.message.addError(L('Requests use this category, so it stays')); return }
    if (ec.entity.find('mantle.request.RequestCategory').condition('parentCategoryId', requestCategoryId).count() > 0) {
        ec.message.addError(L('Other categories are under this one, so it stays')); return }
    ec.entity.find('mantle.request.RequestCategory').condition('requestCategoryId', requestCategoryId).deleteAll()
    message = L('Category deleted')
    return
}
const name = description ? String(description).trim() : ''
if (!name) { ec.message.addError(L('A category needs a name')); return }
if (parentCategoryId) {
    let at = ec.entity.find('mantle.request.RequestCategory').condition('requestCategoryId', parentCategoryId).one()
    if (at == null) { ec.message.addError(ec.resource.expand('Category ${id} not found', '', {id: parentCategoryId})); return }
    for (let depth = 0; at != null && depth < 20; depth++) {
        if (requestCategoryId && at.requestCategoryId === requestCategoryId) { ec.message.addError(L('A category cannot be under itself')); return }
        at = at.parentCategoryId ? ec.entity.find('mantle.request.RequestCategory').condition('requestCategoryId', at.parentCategoryId).one() : null
    }
}
if (responsiblePartyId && ec.entity.find('mantle.party.Party').condition('partyId', responsiblePartyId).one() == null) {
    ec.message.addError(ec.resource.expand('Party ${id} not found', '', {id: responsiblePartyId})); return }
const fields = {description: name.substring(0, 255), parentCategoryId: parentCategoryId || null, responsiblePartyId: responsiblePartyId || null}
if (requestCategoryId) {
    if (ec.entity.find('mantle.request.RequestCategory').condition('requestCategoryId', requestCategoryId).one() == null) {
        ec.message.addError(ec.resource.expand('Category ${id} not found', '', {id: requestCategoryId})); return }
    ec.service.sync().name('update#mantle.request.RequestCategory').parameters(Object.assign({requestCategoryId}, fields)).call()
} else {
    requestCategoryId = ec.service.sync().name('create#mantle.request.RequestCategory').parameters(fields).call()?.requestCategoryId || null
}
if (!ec.message.hasError()) message = L('Category saved')
